/** Enterprise R4 runtime bridge. New workflows live here while legacy read paths remain compatible. */

function r4ContextStore():array{
    global $config;if($config['demo_mode'])return loadStore();$pdo=db();
    $companies=$pdo->query("SELECT id,code,name,business_type type,'violet' color FROM companies WHERE is_active=1 ORDER BY id")->fetchAll();
    $branches=$pdo->query("SELECT id,company_id,code,name,timezone,is_active active FROM branches WHERE is_active=1 ORDER BY company_id,code")->fetchAll();
    $departments=$pdo->query("SELECT id,company_id,branch_id,code,name,cost_center_code,profit_center_code,is_active active FROM departments WHERE is_active=1 ORDER BY company_id,branch_id,code")->fetchAll();
    $accounts=$pdo->query("SELECT id,company_id,code,name,account_type type,parent_id,is_cash_bank cash,is_active active FROM chart_accounts WHERE is_active=1 ORDER BY company_id,code")->fetchAll();
    $users=$pdo->query("SELECT id,name,email,role,company_id,is_active active FROM users WHERE is_active=1 ORDER BY id")->fetchAll();
    $parties=$pdo->query("SELECT id,company_id,party_type,code,name,tax_id,email,phone,address_text,currency,ar_account_id,ap_account_id,is_active active FROM parties WHERE is_active=1 ORDER BY company_id,name")->fetchAll();
    $tax=$pdo->query("SELECT id,code,name,rate,tax_type type,input_account_id,output_account_id,is_active active FROM tax_profiles WHERE is_active=1 ORDER BY id")->fetchAll();
    $banks=$pdo->query("SELECT id,company_id,account_id,bank_name,account_name,account_number,currency,is_active active FROM bank_accounts WHERE is_active=1 ORDER BY company_id,id")->fetchAll();
    $income=$pdo->query("SELECT id,company_id,code,name,revenue_account_id,tax_profile_id,sort_order,is_active active FROM income_categories WHERE is_active=1 ORDER BY company_id,sort_order,id")->fetchAll();
    $curr=$pdo->query("SELECT cr.currency_code code,cr.currency_code name,cr.rate_to_idr rate,cr.rate_date updated_at FROM currency_rates cr JOIN (SELECT currency_code,MAX(rate_date) max_date FROM currency_rates GROUP BY currency_code) x ON x.currency_code=cr.currency_code AND x.max_date=cr.rate_date ORDER BY cr.currency_code")->fetchAll();if(!$curr)$curr=[['code'=>'IDR','name'=>'Indonesian Rupiah','rate'=>1,'updated_at'=>date('Y-m-d')]];
    return ['companies'=>$companies,'branches'=>$branches,'departments'=>$departments,'accounts'=>$accounts,'users'=>$users,'parties'=>$parties,'tax_profiles'=>$tax,'bank_accounts'=>$banks,'income_categories'=>$income,'currencies'=>$curr,'entries'=>[],'invoices'=>[],'approvals'=>[],'meta'=>['approval_threshold'=>(float)($config['approval_threshold']??25000000)]];
}
function r4FileAudit(string $action,array $payload=[]):void{
    $row=['at'=>date('c'),'user'=>$_SESSION['user_name']??'system','action'=>$action,'ip'=>$_SERVER['REMOTE_ADDR']??'cli','payload'=>$payload];
    file_put_contents(auditPath(),json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL,FILE_APPEND|LOCK_EX);
}
function r4MoneyInt(mixed $v):int{if($v===''||$v===null)return 0;if(!is_numeric($v))throw new InvalidArgumentException('Nominal tidak valid.');return (int)round((float)$v);}
function r4JsonArray(mixed $v,string $label):array{if(is_string($v))$v=json_decode($v,true);if(!is_array($v))throw new InvalidArgumentException($label.' tidak valid.');return $v;}
function r4DimensionContext(array $s,int $company,?int $branch,?int $department):array{
    enforceCompanyAccess($s,$company);$branchRow=null;$depRow=null;
    if($branch){foreach($s['branches']??[] as $r)if((int)$r['id']===$branch)$branchRow=$r;if(!$branchRow||(int)$branchRow['company_id']!==$company)throw new RuntimeException('Cabang bukan milik badan usaha terpilih.');}
