    }
    $pdo=db();$st=$pdo->prepare("SELECT id,threshold_amount,max_amount,min_approvers,roles_json,require_distinct_approvers FROM approval_policies WHERE is_active=1 AND document_type=? AND (company_id=? OR company_id IS NULL) AND threshold_amount<=? AND (max_amount IS NULL OR max_amount>=?) ORDER BY company_id IS NULL,level_no DESC,threshold_amount DESC LIMIT 1");$st->execute([$documentType,$company,$amount,$amount]);$r=$st->fetch();
    if(!$r)return ['id'=>null,'required'=>$amount>=$default,'min_approvers'=>1,'threshold'=>$default,'roles'=>['group_owner','group_finance'],'require_distinct'=>true];
    return ['id'=>(int)$r['id'],'required'=>true,'min_approvers'=>max(1,(int)$r['min_approvers']),'threshold'=>(int)round((float)$r['threshold_amount']),'roles'=>$r['roles_json']?json_decode((string)$r['roles_json'],true):[],'require_distinct'=>(bool)$r['require_distinct_approvers']];
