function r4CreateApproval(array $payload,int $company,string $date,string $description,int $amount,string $documentType,int $minApprovers,array $roles=[],?int $policyId=null,bool $requireDistinct=true):array{
    global $config;$s=r4ContextStore();$u=currentUser($s);$roles=array_values(array_unique(array_filter(array_map('strval',$roles))));if(!$roles)$roles=['group_owner','group_finance'];
