function r4LockPeriodDb(PDO $pdo,int $company,string $date):void{$y=(int)substr($date,0,4);$m=(int)substr($date,5,2);$pdo->prepare("INSERT INTO fiscal_periods(company_id,fiscal_year,period,status) VALUES(?,?,?,'open') ON DUPLICATE KEY UPDATE id=id")->execute([$company,$y,$m]);$st=$pdo->prepare("SELECT status FROM fiscal_periods WHERE company_id=? AND fiscal_year=? AND period=? FOR UPDATE");$st->execute([$company,$y,$m]);if(($st->fetchColumn()?:'open')!=='open')throw new RuntimeException('Periode perusahaan '.sprintf('%04d-%02d',$y,$m).' tidak terbuka.');}
