function r4TaxProfile(array $s,?int $id):?array{if(!$id)return null;foreach($s['tax_profiles']??[] as$t)if((int)$t['id']===$id)return$t;return null;}
function r4CreateInvoice(array $input,bool $internalApproved=false):array{
