    foreach($rawIncome as$i=>$r){$cid=(int)($r['category_id']??0);$amount=r4MoneyInt($r['amount']??0);if($amount<=0)continue;$cat=$cats[$cid]??null;if(!$cat)throw new InvalidArgumentException('Kategori pendapatan #'.($i+1).' tidak valid.');$rev=(int)$cat['revenue_account_id'];$a=$am[$rev]??null;if(!$a||($a['type']??'')!=='revenue')throw new RuntimeException('Kategori pendapatan tidak terhubung ke akun revenue.');$taxId=($r['tax_profile_id']??'')!==''?(int)$r['tax_profile_id']:(($cat['tax_profile_id']??null)?(int)$cat['tax_profile_id']:null);$tp=r4TaxProfile($s,$taxId);$mode=(string)($r['tax_mode']??($tp?'inclusive':'none'));$tax=0;$base=$amount;if($tp&&$mode!=='none'&&(float)$tp['rate']>0){$pct=(float)$tp['rate']/100;if($mode==='inclusive'){$base=(int)round($amount/(1+$pct));$tax=$amount-$base;}elseif($mode==='exclusive'){$base=$amount;$tax=(int)round($base*$pct);$amount=$base+$tax;}else throw new InvalidArgumentException('Mode pajak tidak valid.');}$journal[]=['account_id'=>$rev,'debit'=>0,'credit'=>(int)round($base*$rate),'description'=>(string)$cat['name'],'branch_id'=>$branch,'department_id'=>$dept,'project_code'=>$project,'transaction_currency'=>$currency,'foreign_amount'=>$base,'exchange_rate'=>$rate];if($tax>0){$taxAcc=(int)($tp['output_account_id']??0);if(!$taxAcc)throw new RuntimeException('Tax profile tidak mempunyai akun pajak keluaran.');$journal[]=['account_id'=>$taxAcc,'debit'=>0,'credit'=>(int)round($tax*$rate),'description'=>'Pajak · '.$cat['name'],'branch_id'=>$branch,'department_id'=>$dept,'project_code'=>$project,'transaction_currency'=>$currency,'foreign_amount'=>$tax,'exchange_rate'=>$rate];$taxRows[]=['tax_profile_id'=>$taxId,'tax_base'=>$base,'tax_amount'=>$tax,'direction'=>'output','tax_code'=>$tp['code']??null];}$incomeGross+=$amount;$normalizedIncome[]=['category_id'=>$cid,'name'=>$cat['name'],'gross'=>$amount,'base'=>$base,'tax'=>$tax,'tax_profile_id'=>$taxId];}
    if($incomeGross<=0)throw new InvalidArgumentException('Minimal satu pendapatan harus diisi.');$paymentGross=0;$settlements=[];foreach($rawPayments as$i=>$r){$aid=(int)($r['account_id']??0);$gross=r4MoneyInt($r['gross_amount']??$r['amount']??0);$fee=r4MoneyInt($r['fee_amount']??0);$feeAcc=(int)($r['fee_account_id']??0);$channel=trim((string)($r['channel']??'Cash/Bank'));$ref=trim((string)($r['external_ref']??''));if($gross<=0)continue;if($fee<0||$fee>$gross)throw new InvalidArgumentException('Fee settlement #'.($i+1).' tidak valid.');$a=$am[$aid]??null;if(!$a||empty($a['cash']))throw new InvalidArgumentException('Payment line harus menggunakan akun Kas/Bank.');$owner=(int)($a['company_id']??0);if($owner!==0&&$owner!==$company)throw new RuntimeException('Akun settlement berbeda badan usaha.');$net=$gross-$fee;$journal[]=['account_id'=>$aid,'debit'=>(int)round($net*$rate),'credit'=>0,'description'=>$channel.' net receipt','branch_id'=>$branch,'department_id'=>$dept,'project_code'=>$project,'transaction_currency'=>$currency,'foreign_amount'=>$net,'exchange_rate'=>$rate];if($fee>0){if(!$feeAcc)throw new InvalidArgumentException('Fee account wajib jika fee settlement lebih dari nol.');$fa=$am[$feeAcc]??null;if(!$fa||($fa['type']??'')!=='expense')throw new InvalidArgumentException('Fee account harus bertipe expense.');$journal[]=['account_id'=>$feeAcc,'debit'=>(int)round($fee*$rate),'credit'=>0,'description'=>'Fee '.$channel,'branch_id'=>$branch,'department_id'=>$dept,'project_code'=>$project,'transaction_currency'=>$currency,'foreign_amount'=>$fee,'exchange_rate'=>$rate];}$paymentGross+=$gross;$settlements[]=['account_id'=>$aid,'gross_amount'=>$gross,'fee_amount'=>$fee,'net_amount'=>$net,'channel'=>$channel,'external_ref'=>$ref];}
