    if($config['demo_mode']){foreach($s['assets']??[] as$a){if((int)$a['company_id']!==$company)continue;$cost=(int)round((float)$a['cost']);$book=(int)round((float)$a['book']);$life=(int)($a['useful_life_months']??120);$res=(int)($a['residual_value']??0);$monthly=(int)round(max(0,$cost-$res)/max(1,$life));$amount=min($monthly,max(0,$book-$res));if($amount<=0)continue;$exists=false;foreach($s['asset_depreciation_schedule']??[] as$x)if((int)$x['asset_id']===(int)$a['id']&&$x['period']===$period)$exists=true;if($exists)continue;$entry=r4PostMultiLineJournal(['company_id'=>$company,'date'=>$date,'description'=>'Depresiasi '.$a['name'].' '.$period,'source'=>'depreciation','lines'=>[['account_id'=>12,'debit'=>$amount,'credit'=>0,'description'=>'Beban depresiasi'],['account_id'=>11,'debit'=>0,'credit'=>$amount,'description'=>'Akumulasi penyusutan']]],true);$sid=(int)($s['meta']['next_dep_schedule_id']??1);$s=loadStore();$s['asset_depreciation_schedule'][]=['id'=>$sid,'asset_id'=>$a['id'],'period'=>$period,'depreciation_amount'=>$amount,'accumulated_amount'=>$cost-$book+$amount,'book_value'=>$book-$amount,'journal_id'=>$entry['id'],'status'=>'posted'];foreach($s['assets'] as&$aa)if((int)$aa['id']===(int)$a['id'])$aa['book']=$book-$amount;unset($aa);$s['meta']['next_dep_schedule_id']=$sid+1;saveStore($s);$posted[]=['asset_id'=>$a['id'],'amount'=>$amount,'journal_id'=>$entry['id']];}r4FileAudit('depreciation.period_posted',['company_id'=>$company,'period'=>$period,'count'=>count($posted)]);return['period'=>$period,'posted'=>$posted];}
    $pdo=db();$q=$pdo->prepare("SELECT * FROM fixed_assets WHERE company_id=? AND status='active' AND acquisition_date<=?");$q->execute([$company,$date]);$assets=$q->fetchAll();foreach($assets as$a){$check=$pdo->prepare("SELECT status FROM asset_depreciation_schedule WHERE asset_id=? AND period=?");$check->execute([$a['id'],$period]);if($check->fetchColumn())continue;$cost=(int)round((float)$a['acquisition_cost']);$res=(int)round((float)$a['residual_value']);$life=max(1,(int)$a['useful_life_months']);$monthly=(int)round(($cost-$res)/$life);$sum=$pdo->prepare("SELECT COALESCE(SUM(depreciation_amount),0) FROM asset_depreciation_schedule WHERE asset_id=? AND status='posted'");$sum->execute([$a['id']]);$acc=(int)round((float)$sum->fetchColumn());$amount=min($monthly,max(0,$cost-$res-$acc));if($amount<=0)continue;$expense=(int)($a['depreciation_expense_account_id']?:accountIdByCode($s,$company,'5301'));$accum=(int)($a['accumulated_depreciation_account_id']?:accountIdByCode($s,$company,'1191'));$entry=r4PostMultiLineJournal(['company_id'=>$company,'branch_id'=>$a['branch_id']?:null,'department_id'=>$a['department_id']?:null,'date'=>$date,'description'=>'Depresiasi '.$a['name'].' '.$period,'source'=>'depreciation','lines'=>[['account_id'=>$expense,'debit'=>$amount,'credit'=>0,'description'=>'Beban depresiasi'],['account_id'=>$accum,'debit'=>0,'credit'=>$amount,'description'=>'Akumulasi penyusutan']]],true);$st=$pdo->prepare("INSERT INTO asset_depreciation_schedule(asset_id,period,depreciation_amount,accumulated_amount,book_value,journal_id,status) VALUES(?,?,?,?,?,?,'posted')");$st->execute([$a['id'],$period,$amount,$acc+$amount,$cost-$acc-$amount,$entry['id']]);$posted[]=['asset_id'=>(int)$a['id'],'amount'=>$amount,'journal_id'=>$entry['id']];}writeAudit('depreciation.period_posted',['company_id'=>$company,'period'=>$period,'count'=>count($posted)]);return['period'=>$period,'posted'=>$posted];
}
function r4SaveFxRate(array $input):array{
    global $config;$s=r4ContextStore();requireAbility('fx.manage',$s);$date=(string)($input['date']??date('Y-m-d'));$base=strtoupper((string)($input['base_currency']??'USD'));$quote=strtoupper((string)($input['quote_currency']??'IDR'));$rate=(float)($input['rate']??0);$source=trim((string)($input['source']??'manual'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^[A-Z]{3}$/',$base)||!preg_match('/^[A-Z]{3}$/',$quote)||$rate<=0)throw new InvalidArgumentException('FX rate tidak valid.');if($config['demo_mode']){$id=(int)($s['meta']['next_fx_rate_id']??1);$row=['id'=>$id,'rate_date'=>$date,'base_currency'=>$base,'quote_currency'=>$quote,'rate'=>$rate,'source'=>$source];$s['fx_rates'][]=$row;$s['meta']['next_fx_rate_id']=$id+1;saveStore($s);r4FileAudit('fx.rate_saved',$row);return$row;}$pdo=db();$st=$pdo->prepare("INSERT INTO fx_rates(rate_date,base_currency,quote_currency,rate,source) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE rate=VALUES(rate)");$st->execute([$date,$base,$quote,$rate,$source]);writeAudit('fx.rate_saved',['date'=>$date,'base'=>$base,'quote'=>$quote,'rate'=>$rate]);return['rate_date'=>$date,'base_currency'=>$base,'quote_currency'=>$quote,'rate'=>$rate,'source'=>$source];
}
function r4PostFxRevaluation(array $input):array{
    global $config;$s=r4ContextStore();requireAbility('fx.manage',$s);$company=(int)($input['company_id']??0);$period=(string)($input['period']??date('Y-m'));$currency=strtoupper((string)($input['currency']??'USD'));$account=(int)($input['account_id']??0);$foreign=r4MoneyInt($input['foreign_balance']??0);$bookBase=r4MoneyInt($input['book_base_amount']??0);$rate=(float)($input['closing_rate']??0);if(!$company||!preg_match('/^\d{4}-\d{2}$/',$period)||!$account||$foreign<0||$rate<=0)throw new InvalidArgumentException('Data revaluation tidak valid.');enforceCompanyAccess($s,$company);$a=accountMap($s)[$account]??null;if(!$a)throw new RuntimeException('Akun revaluation tidak ditemukan.');$closing=(int)round($foreign*$rate);$diff=$closing-$bookBase;if($diff===0)return['status'=>'no_change','gain_loss'=>0];$fx=accountIdByCode($s,$company,'7101');$isLiab=$a['type']==='liability';$gain=$isLiab?-$diff:$diff;$date=$period.'-'.date('t',strtotime($period.'-01'));$lines=$gain>0?[['account_id'=>$account,'debit'=>$isLiab?0:abs($diff),'credit'=>$isLiab?abs($diff):0,'description'=>'FX revaluation '.$currency],['account_id'=>$fx,'debit'=>0,'credit'=>abs($diff),'description'=>'FX gain']]:[['account_id'=>$fx,'debit'=>abs($diff),'credit'=>0,'description'=>'FX loss'],['account_id'=>$account,'debit'=>$isLiab?abs($diff):0,'credit'=>$isLiab?0:abs($diff),'description'=>'FX revaluation '.$currency]];$entry=r4PostMultiLineJournal(['company_id'=>$company,'date'=>$date,'description'=>'Revaluasi '.$currency.' '.$period,'source'=>'fx_revaluation','lines'=>$lines],true);
    if($config['demo_mode']){$id=(int)($s['meta']['next_fx_revaluation_id']??1);$s=loadStore();$s['fx_revaluation_runs'][]=['id'=>$id,'company_id'=>$company,'period'=>$period,'currency'=>$currency,'closing_rate'=>$rate,'gain_loss_amount'=>$gain,'journal_id'=>$entry['id'],'status'=>'posted'];$s['meta']['next_fx_revaluation_id']=$id+1;saveStore($s);return['id'=>$id,'journal_id'=>$entry['id'],'gain_loss'=>$gain];}$pdo=db();$st=$pdo->prepare("INSERT INTO fx_revaluation_runs(company_id,period,currency,closing_rate,gain_loss_amount,journal_id,status,created_by) VALUES(?,?,?,?,?,?,'posted',?) ON DUPLICATE KEY UPDATE closing_rate=VALUES(closing_rate),gain_loss_amount=VALUES(gain_loss_amount),journal_id=VALUES(journal_id),status='posted'");$st->execute([$company,$period,$currency,$rate,$gain,$entry['id'],$_SESSION['user_id']??null]);writeAudit('fx.revaluation_posted',['company_id'=>$company,'period'=>$period,'gain_loss'=>$gain]);return['journal_id'=>$entry['id'],'gain_loss'=>$gain];
}
function r4ClosePeriod(array $input):array{
    global $config;$s=r4ContextStore();requireAbility('period.manage',$s);$company=(int)($input['company_id']??0);$year=(int)($input['year']??0);$month=(int)($input['month']??0);if(!$company||$year<2000||$month<1||$month>12)throw new InvalidArgumentException('Periode closing tidak valid.');enforceCompanyAccess($s,$company);$period=sprintf('%04d-%02d',$year,$month);
    if($config['demo_mode']){$checks=[];$checks['pending_approvals']=count(array_filter($s['approvals']??[],fn($a)=>(int)($a['company_id']??0)===$company&&($a['status']??'')==='pending'&&str_starts_with((string)$a['date'],$period)))===0;$checks['bank_reconciliation']=count(array_filter($s['bank_feed']??[],fn($r)=>(int)$r['company_id']===$company&&($r['status']??'')==='unmatched'&&str_starts_with((string)$r['date'],$period)))===0;$checks['tax_review']=count(array_filter($s['tax_transactions']??[],fn($r)=>(int)$r['company_id']===$company&&($r['status']??'open')==='open'&&str_starts_with((string)$r['transaction_date'],$period)))===0;$checks['depreciation']=true;$checks['arap_review']=count(array_filter($s['invoices']??[],fn($r)=>(int)$r['company_id']===$company&&in_array($r['status'],['open','partial'],true)&&$r['due_date']<$period.'-'.date('t',strtotime($period.'-01'))))===0;$checks['intercompany']=true;$checks['trial_balance']=true;if(in_array(false,$checks,true))throw new RuntimeException('Closing ditolak. Checklist belum PASS: '.implode(', ',array_keys(array_filter($checks,fn($v)=>!$v))));$found=false;foreach($s['periods'] as&$p)if((int)($p['company_id']??$company)===$company&&(int)$p['year']===$year&&(int)$p['month']===$month){$p['company_id']=$company;$p['status']='closed';$p['closed_at']=date('Y-m-d H:i:s');$p['closed_by']=currentUser($s)['id'];$found=true;}unset($p);if(!$found)$s['periods'][]=['id'=>count($s['periods'])+1,'company_id'=>$company,'year'=>$year,'month'=>$month,'status'=>'closed','closed_at'=>date('Y-m-d H:i:s'),'closed_by'=>currentUser($s)['id']];foreach($checks as$code=>$ok)$s['period_close_tasks'][]=['company_id'=>$company,'year'=>$year,'month'=>$month,'task_code'=>$code,'status'=>$ok?'passed':'pending'];saveStore($s);r4FileAudit('period.closed_r4',['company_id'=>$company,'period'=>$period]);return['company_id'=>$company,'period'=>$period,'status'=>'closed','checks'=>$checks];}
    $pdo=db();$svc=new \Nexa\Closing\PeriodCloseService($pdo);$evaluation=$svc->evaluate($company,$year,$month);$svc->persistTasks($evaluation,(int)($_SESSION['user_id']??0));if(!$evaluation['ready'])throw new RuntimeException('Closing ditolak. Checklist enterprise belum seluruhnya PASS.');$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO fiscal_periods(company_id,fiscal_year,period,status,closed_at,closed_by) VALUES(?,?,?,'closed',NOW(),?) ON DUPLICATE KEY UPDATE status='closed',closed_at=NOW(),closed_by=VALUES(closed_by)")->execute([$company,$year,$month,$_SESSION['user_id']??null]);(new \Nexa\Audit\TransactionalAuditService($pdo))->record('period.closed_r4','fiscal_period',$period,$evaluation,(int)($_SESSION['user_id']??0),$company);$pdo->commit();}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}r4FileAudit('period.closed_r4',['company_id'=>$company,'period'=>$period]);return$evaluation+['status'=>'closed'];
}

function r4ReportFilters(?int $companyId=null):array{
    $period=(string)($_GET['period']??date('Y-m'));$start=(string)($_GET['start_date']??($period.'-01'));$end=(string)($_GET['end_date']??date('Y-m-t',strtotime($period.'-01')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end=date('Y-m-t');return ['company_id'=>$companyId?:null,'branch_id'=>max(0,(int)($_GET['branch_id']??0))?:null,'department_id'=>max(0,(int)($_GET['department_id']??0))?:null,'account_id'=>max(0,(int)($_GET['account_id']??0))?:null,'currency'=>preg_match('/^[A-Z]{3}$/',(string)($_GET['currency']??''))?(string)$_GET['currency']:null,'start'=>$start,'end'=>$end,'period'=>substr($start,0,7)];
}
function r4SqlBalanceSheet(PDO $pdo,array $f):array{
    $where=["je.status='posted'","je.journal_date<=?"];$p=[$f['end']];if($f['company_id']){$where[]='je.company_id=?';$p[]=$f['company_id'];}if($f['branch_id']){$where[]='COALESCE(jl.branch_id,je.branch_id)=?';$p[]=$f['branch_id'];}if($f['department_id']){$where[]='COALESCE(jl.department_id,je.department_id)=?';$p[]=$f['department_id'];}
    $sql="SELECT a.account_type type,SUM(CASE WHEN a.account_type='asset' THEN jl.debit-jl.credit ELSE jl.credit-jl.debit END) amount FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id JOIN chart_accounts a ON a.id=jl.account_id WHERE ".implode(' AND ',$where)." AND a.account_type IN('asset','liability','equity') GROUP BY a.account_type";$st=$pdo->prepare($sql);$st->execute($p);$v=['asset'=>0.0,'liability'=>0.0,'equity'=>0.0];foreach($st->fetchAll() as$r)$v[$r['type']]=(float)$r['amount'];
    $earnWhere=["je.status='posted'","je.journal_date<=?","je.source_type<>'year_end_close'","a.account_type IN('revenue','expense')","je.journal_date>COALESCE((SELECT MAX(y.close_date) FROM year_end_closes y WHERE y.company_id=je.company_id AND y.status='posted' AND y.close_date<=?),'1900-01-01')"];$ep=[$f['end'],$f['end']];if($f['company_id']){$earnWhere[]='je.company_id=?';$ep[]=$f['company_id'];}if($f['branch_id']){$earnWhere[]='COALESCE(jl.branch_id,je.branch_id)=?';$ep[]=$f['branch_id'];}if($f['department_id']){$earnWhere[]='COALESCE(jl.department_id,je.department_id)=?';$ep[]=$f['department_id'];}
    $eq="SELECT COALESCE(SUM(CASE WHEN a.account_type='revenue' THEN jl.credit-jl.debit ELSE -(jl.debit-jl.credit) END),0) FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id JOIN chart_accounts a ON a.id=jl.account_id WHERE ".implode(' AND ',$earnWhere);$st=$pdo->prepare($eq);$st->execute($ep);$currentProfit=(float)$st->fetchColumn();$equity=$v['equity']+$currentProfit;return ['assets'=>$v['asset'],'liabilities'=>$v['liability'],'equity'=>$equity,'retained_current_profit'=>$currentProfit,'net_assets'=>$v['asset']-$v['liability'],'difference'=>$v['asset']-($v['liability']+$equity)];
}
function r4SqlCashflow(PDO $pdo,array $f,int $months=12):array{
    $start=date('Y-m-01',strtotime($f['end'].' -'.($months-1).' months'));$where=["je.status='posted'","je.journal_date BETWEEN ? AND ?","a.is_cash_bank=1"];$p=[$start,$f['end']];if($f['company_id']){$where[]='je.company_id=?';$p[]=$f['company_id'];}if($f['branch_id']){$where[]='COALESCE(jl.branch_id,je.branch_id)=?';$p[]=$f['branch_id'];}if($f['department_id']){$where[]='COALESCE(jl.department_id,je.department_id)=?';$p[]=$f['department_id'];}$sql="SELECT DATE_FORMAT(je.journal_date,'%Y-%m') m,je.source_type,SUM(jl.debit-jl.credit) cash_delta FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id JOIN chart_accounts a ON a.id=jl.account_id WHERE ".implode(' AND ',$where)." GROUP BY DATE_FORMAT(je.journal_date,'%Y-%m'),je.source_type ORDER BY m";$st=$pdo->prepare($sql);$st->execute($p);$map=[];foreach($st->fetchAll() as$r){$m=$r['m'];$map[$m]??=['m'=>$m,'operating'=>0.0,'investing'=>0.0,'financing'=>0.0];$source=(string)$r['source_type'];$bucket=in_array($source,['asset_acquisition','asset_disposal'],true)?'investing':(in_array($source,['capital','loan','intercompany','fx_revaluation'],true)?'financing':'operating');$map[$m][$bucket]+=(float)$r['cash_delta']/1000000;}return array_values($map);
}
function r4SqlCompanyMetrics(PDO $pdo,array $f):array{
    $where=["c.is_active=1"];$params=[];$date="je.journal_date BETWEEN ? AND ?";$params=[$f['start'],$f['end']];$sql="SELECT c.id,c.code,c.name,c.business_type type,'violet' color,COALESCE(SUM(CASE WHEN je.status='posted' AND je.source_type<>'year_end_close' AND $date AND a.account_type='revenue' THEN jl.credit-jl.debit ELSE 0 END),0) revenue,COALESCE(SUM(CASE WHEN je.status='posted' AND je.source_type<>'year_end_close' AND $date AND a.account_type='expense' THEN jl.debit-jl.credit ELSE 0 END),0) expense,COALESCE(SUM(CASE WHEN je.status='posted' AND a.is_cash_bank=1 THEN jl.debit-jl.credit ELSE 0 END),0) cash FROM companies c LEFT JOIN journal_entries je ON je.company_id=c.id LEFT JOIN journal_lines jl ON jl.journal_id=je.id LEFT JOIN chart_accounts a ON a.id=jl.account_id WHERE c.is_active=1 GROUP BY c.id,c.code,c.name,c.business_type ORDER BY c.id";$st=$pdo->prepare($sql);$st->execute($params);$out=[];foreach($st->fetchAll() as$r){$r['revenue']=(float)$r['revenue'];$r['expense']=(float)$r['expense'];$r['cash']=(float)$r['cash'];$r['profit']=$r['revenue']-$r['expense'];$r['margin']=$r['revenue']?$r['profit']/$r['revenue']*100:0;$out[]=$r;}return$out;
}
function r4ProductionConsolidationStore(PDO $pdo,string $period):array{
    $accounts=$pdo->query("SELECT id,company_id,code,name,account_type type,is_cash_bank cash FROM chart_accounts WHERE is_active=1")->fetchAll();$q=$pdo->prepare("SELECT id,period,status FROM consolidation_runs WHERE period=? AND status IN('posted','locked')");$q->execute([$period]);$runs=$q->fetchAll();$entries=[];if($runs){$ids=array_map(fn($r)=>(int)$r['id'],$runs);$ph=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT id,consolidation_run_id,from_company_id,to_company_id,account_id,branch_id,department_id,debit,credit,reference,description FROM elimination_entries WHERE consolidation_run_id IN ($ph)");$q->execute($ids);$entries=$q->fetchAll();}return ['accounts'=>$accounts,'consolidation_runs'=>$runs,'elimination_entries'=>$entries];
}
function r4FinancialReportDataProduction(?int $companyId=null):array{
    $pdo=db();$ctx=r4ContextStore();$u=currentUser($ctx);if(!$u)throw new RuntimeException('Autentikasi diperlukan.');if(($u['role']??'')==='entity_admin'){$assigned=(int)($u['company_id']??0);if(!$assigned)throw new RuntimeException('Entity Admin belum memiliki scope perusahaan.');if($companyId&&$companyId!==$assigned)throw new RuntimeException('Akses laporan lintas entitas ditolak.');$companyId=$assigned;}$f=r4ReportFilters($companyId);$svc=new \Nexa\Reports\SqlReportService($pdo);$pnl=$svc->pnl($f);$balance=r4SqlBalanceSheet($pdo,$f);$metrics=$pnl+['cash'=>0.0,'assets'=>$balance['assets'],'liabilities'=>$balance['liabilities'],'equity'=>$balance['equity'],'tx'=>0,'margin'=>$pnl['revenue']?$pnl['profit']/$pnl['revenue']*100:0];$cashQ="SELECT COALESCE(SUM(jl.debit-jl.credit),0) FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id JOIN chart_accounts a ON a.id=jl.account_id WHERE je.status='posted' AND a.is_cash_bank=1";$args=[];if($companyId){$cashQ.=' AND je.company_id=?';$args[]=$companyId;}$q=$pdo->prepare($cashQ);$q->execute($args);$metrics['cash']=(float)$q->fetchColumn();$txQ="SELECT COUNT(*) FROM journal_entries WHERE status='posted' AND journal_date BETWEEN ? AND ?";$args=[$f['start'],$f['end']];if($companyId){$txQ.=' AND company_id=?';$args[]=$companyId;}$q=$pdo->prepare($txQ);$q->execute($args);$metrics['tx']=(int)$q->fetchColumn();$companies=r4SqlCompanyMetrics($pdo,$f);if($companyId)$companies=array_values(array_filter($companies,fn($c)=>(int)$c['id']===$companyId));$ledger=$svc->ledger($f,500,0);$transactions=[];$cm=[];foreach($companies as$c)$cm[(int)$c['id']]=$c;foreach($ledger as$l)$transactions[]=['id'=>$l['id'],'no'=>$l['journal_no'],'date'=>$l['journal_date'],'company'=>$cm[(int)$l['company_id']]['name']??('Entity '.$l['company_id']),'desc'=>$l['description'],'account'=>$l['account_code'].' · '.$l['account_name'],'amount'=>max((float)$l['debit'],(float)$l['credit']),'status'=>'Posted','branch_id'=>$l['branch_id'],'department_id'=>$l['department_id'],'currency'=>$l['transaction_currency']];$trial=$svc->trialBalance($f);$interQ="SELECT je.journal_date date,cf.name `from`,ct.name `to`,je.description,MAX(jl.debit+jl.credit) amount,'Matched' status FROM journal_entries je JOIN journal_lines jl ON jl.journal_id=je.id JOIN companies cf ON cf.id=je.company_id JOIN companies ct ON ct.id=jl.intercompany_company_id WHERE je.status='posted' AND je.journal_date BETWEEN ? AND ? AND jl.intercompany_company_id IS NOT NULL GROUP BY je.id,je.journal_date,cf.name,ct.name,je.description ORDER BY je.journal_date DESC";$q=$pdo->prepare($interQ);$q->execute([$f['start'],$f['end']]);$report=['company_id'=>$companyId,'companies'=>$companies,'metrics'=>$metrics,'transactions'=>$transactions,'cashflow'=>r4SqlCashflow($pdo,$f,12),'trial_balance'=>$trial,'balance_sheet'=>$balance,'intercompany'=>$q->fetchAll(),'period'=>['key'=>substr($f['start'],0,7),'label'=>monthLabel(substr($f['start'],0,7))],'filters'=>$f];if(!$companyId){$cs=r4ProductionConsolidationStore($pdo,substr($f['start'],0,7));$report=r4ApplyConsolidationToReport($report,$cs,substr($f['start'],0,7));}return$report;
