function r4AdjustInvoice(array $input,bool $internalApproved=false):array{
    global $config;$s=$config['demo_mode']?loadStore():r4ContextStore();requireAbility('arap.manage',$s);$invoiceId=(int)($input['invoice_id']??0);$type=(string)($input['adjustment_type']??'credit_note');$amount=r4MoneyInt($input['amount']??0);$date=(string)($input['date']??date('Y-m-d'));$reason=trim((string)($input['reason']??''));$offset=(int)($input['offset_account_id']??0);if(!$invoiceId||!in_array($type,['credit_note','debit_note','writeoff'],true)||$amount<=0||!$offset||strlen($reason)<3)throw new InvalidArgumentException('Invoice adjustment tidak valid.');$inv=null;foreach($s['invoices']??[] as$i)if((int)$i['id']===$invoiceId)$inv=$i;if(!$inv&& !$config['demo_mode']){$q=db()->prepare("SELECT id,company_id,branch_id,department_id,invoice_type type,invoice_no number,party_name party,amount,paid_amount paid,status,currency FROM invoices WHERE id=?");$q->execute([$invoiceId]);$inv=$q->fetch();}if(!$inv)throw new RuntimeException('Invoice tidak ditemukan.');$company=(int)$inv['company_id'];enforceCompanyAccess($s,$company);$open=(int)round((float)$inv['amount']-(float)($inv['paid']??0));if($amount>$open)throw new RuntimeException('Adjustment melebihi outstanding invoice.');$policy=r4ApprovalPolicy($s,$company,'invoice_adjustment',$amount);if($policy['required']&&!$internalApproved){$payload=['kind'=>'r4_invoice_adjustment']+$input;$approval=r4CreateApproval($payload,$company,$date,strtoupper($type).' '.$inv['number'].' · '.$reason,$amount,'invoice_adjustment',$policy['min_approvers'],$policy['roles']??[],$policy['id']??null,$policy['require_distinct']??true);return['approval_required'=>true,'approval'=>$approval,'amount'=>$amount];}$ar=accountIdByCode($s,$company,'1102');$ap=accountIdByCode($s,$company,'2101');$lines=[];if($inv['type']==='receivable'){$lines=[['account_id'=>$offset,'debit'=>$amount,'credit'=>0,'description'=>$type.' '.$inv['number']],['account_id'=>$ar,'debit'=>0,'credit'=>$amount,'description'=>'Reduce receivable']];}else{$lines=[['account_id'=>$ap,'debit'=>$amount,'credit'=>0,'description'=>'Reduce payable'],['account_id'=>$offset,'debit'=>0,'credit'=>$amount,'description'=>$type.' '.$inv['number']]];}$entry=r4PostMultiLineJournal(['company_id'=>$company,'branch_id'=>$inv['branch_id']??null,'department_id'=>$inv['department_id']??null,'date'=>$date,'description'=>strtoupper($type).' '.$inv['number'].' · '.$reason,'source'=>'invoice_adjustment','document_type'=>'invoice_adjustment','lines'=>$lines],true);
    if($config['demo_mode']){$s=loadStore();$id=count($s['invoice_adjustments']??[])+1;$s['invoice_adjustments'][]=['id'=>$id,'invoice_id'=>$invoiceId,'adjustment_type'=>$type,'adjustment_no'=>'ADJ-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'adjustment_date'=>$date,'amount'=>$amount,'reason'=>$reason,'journal_id'=>$entry['id']];foreach($s['invoices'] as&$i)if((int)$i['id']===$invoiceId){$i['amount']=(float)$i['amount']-$amount;if((float)$i['amount']<=(float)$i['paid'])$i['status']='paid';}unset($i);saveStore($s);return['id'=>$id,'journal_id'=>$entry['id'],'amount'=>$amount];}
    $pdo=db();$pdo->beginTransaction();try{$seq=new \Nexa\Infrastructure\Persistence\PdoDocumentSequence($pdo);$no=$seq->next($company,'invoice_adjustment',$date,'ADJ');$pdo->prepare("INSERT INTO invoice_adjustments(invoice_id,adjustment_type,adjustment_no,adjustment_date,amount,reason,journal_id,created_by) VALUES(?,?,?,?,?,?,?,?)")->execute([$invoiceId,$type,$no,$date,$amount,$reason,$entry['id'],$_SESSION['user_id']??null]);$id=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE invoices SET amount=GREATEST(paid_amount,amount-?),status=CASE WHEN amount-?<=paid_amount THEN 'paid' ELSE status END WHERE id=?")->execute([$amount,$amount,$invoiceId]);(new \Nexa\Audit\TransactionalAuditService($pdo))->record('invoice.adjusted','invoice',(string)$invoiceId,['adjustment_id'=>$id,'type'=>$type,'amount'=>$amount,'journal_id'=>$entry['id']],(int)($_SESSION['user_id']??0),$company);$pdo->commit();}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}return['id'=>$id,'journal_id'=>$entry['id'],'amount'=>$amount,'adjustment_no'=>$no];
}
